const ELEMENT_PROP_KEYS = new Set(["theme","stagger","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  stagger: 3,
  hold: 28,
  fontFamily: "Funnel Display",
  scale: 1,
  delay: 0,
  speed: 1,
};

type CoyDenialElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CoyDenialBase>;

const CoyDenialInner = forwardRef<
  HTMLDivElement,
  CoyDenialElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CoyDenial>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CoyDenialBase
          {...(componentProps as unknown as ComponentProps<typeof CoyDenialBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CoyDenial = Interactive.withSchema({
  Component: CoyDenialInner,
  componentName: "<CoyDenial>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
